//! `approx_eq` must reproduce Foundry's `assertApproxEqRelN` exactly.
//!
//! The expected values in `tests/data/approx_cases.txt` were generated by transcribing
//! `percentDeltaN` and `assertApproxEqRelN` from the Basin `TestHelper`, then computing
//! them in Python. Predicting them from Rust would beg the question.
//!
//! Format: `a b tolerance_bps precision expected_pass percent_delta|na`

use rustyfuzz_predicate::{
    BindingManifest, BlockContext, EvalContext, Outcome, ReReadBudget, Resolver, StateReader,
    WriteRecord,
};
use std::collections::BTreeMap;

const MANIFEST: &str = r#"{
    "target": "0x00000000000000000000000000000000000000aa",
    "symbols": {
        "lpSupply": { "kind": "slot", "slot": "0x1", "offset_bits": 0, "width_bits": 256 },
        "functionCalc": { "kind": "slot", "slot": "0x2", "offset_bits": 0, "width_bits": 256 }
    }
}"#;

struct NoRead;

impl StateReader for NoRead {
    fn read_slot(&mut self, _address: [u8; 20], _slot: [u8; 32]) -> Option<[u8; 32]> {
        None
    }
}

fn big_endian(value: &str) -> [u8; 32] {
    // Decimal string to a 256-bit big-endian word without pulling in a bignum crate.
    let mut bytes = [0u8; 32];
    for ch in value.chars() {
        let digit = ch.to_digit(10).expect("decimal digit") as u16;
        let mut carry = digit;
        for byte in bytes.iter_mut().rev() {
            let acc = u16::from(*byte) * 10 + carry;
            *byte = (acc & 0xFF) as u8;
            carry = acc >> 8;
        }
    }
    bytes
}

fn evaluate_approx(a: &str, b: &str, tolerance: u64, precision: u64) -> Outcome {
    let bindings = BindingManifest::from_json(MANIFEST)
        .expect("parses")
        .resolve()
        .expect("resolves");
    let source = format!("approx_eq(lpSupply, functionCalc, {tolerance}, {precision})");
    let checked = rustyfuzz_predicate::compile(&source).expect("compiles");

    let mut slot_a = [0u8; 32];
    slot_a[31] = 1;
    let mut slot_b = [0u8; 32];
    slot_b[31] = 2;
    let mut address = [0u8; 20];
    address[19] = 0xaa;

    let writes = vec![
        WriteRecord {
            tx_index: 0,
            address,
            slot: slot_a,
            old_value: [0u8; 32],
            new_value: big_endian(a),
        },
        WriteRecord {
            tx_index: 0,
            address,
            slot: slot_b,
            old_value: [0u8; 32],
            new_value: big_endian(b),
        },
    ];
    let resolver = Resolver::new(&bindings, &writes, &[], 0);
    let ctx = EvalContext {
        bindings: &bindings,
        resolver: &resolver,
        block: BlockContext::default(),
        tx_index: 0,
    };
    let mut reader = NoRead;
    let (outcome, _, _) =
        rustyfuzz_predicate::evaluate(checked.expr(), &ctx, &mut reader, ReReadBudget::new(4));
    outcome
}

#[test]
fn approx_eq_matches_foundry_assert_approx_eq_rel_n() {
    let data = include_str!("data/approx_cases.txt");
    let mut checked = 0usize;
    for (line_number, line) in data.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split_whitespace().collect();
        assert_eq!(
            fields.len(),
            6,
            "malformed case on line {}",
            line_number + 1
        );

        let a = fields[0];
        let b = fields[1];
        let tolerance: u64 = fields[2].parse().expect("tolerance");
        let precision: u64 = fields[3].parse().expect("precision");
        let expected_pass = fields[4] == "1";

        let outcome = evaluate_approx(a, b, tolerance, precision);
        let passed = outcome.is_clean_pass();
        assert_eq!(
            passed,
            expected_pass,
            "case {}: approx_eq({a}, {b}, {tolerance}, {precision}) should be {}, got {outcome:?}",
            line_number + 1,
            if expected_pass { "pass" } else { "FAIL" }
        );
        // A failure must be a violation, never an Unknown: the arithmetic is decidable
        // whenever both operands resolved, and reporting Unknown would hide a real
        // divergence behind "no signal".
        assert!(
            !matches!(outcome, Outcome::Unknown(_)),
            "case {} must be decidable",
            line_number + 1
        );
        checked += 1;
    }
    assert!(checked >= 10, "expected at least 10 cases, ran {checked}");
}

/// The integer-division subtlety, called out because it is counter-intuitive and is
/// exactly what a naive implementation gets wrong.
#[test]
fn at_precision_zero_any_delta_smaller_than_b_passes_even_with_zero_tolerance() {
    // percentDelta = (|a-b| * 1) / b, and 1/1_000_000 == 0 under integer division.
    let outcome = evaluate_approx("1000001", "1000000", 0, 0);
    assert!(
        outcome.is_clean_pass(),
        "Foundry passes this; the integer division truncates the delta to zero, got {outcome:?}"
    );
}

/// The zero-expected special case is on `b`, and demands exact equality.
#[test]
fn a_zero_expected_value_requires_exact_equality_regardless_of_tolerance() {
    assert!(
        evaluate_approx("0", "0", 0, 6).is_clean_pass(),
        "both zero is equal"
    );
    assert!(
        evaluate_approx("5", "0", 1_000_000_000_000_000_000, 6).is_violation(),
        "a non-zero actual against a zero expected must fail even with a huge tolerance"
    );
}

/// 100% delta sits exactly on the boundary: it passes only if the tolerance allows it.
#[test]
fn a_doubling_is_exactly_one_hundred_percent_and_the_boundary_is_inclusive() {
    let hundred_percent = 1_000_000_000_000_000_000u64; // 1e18
    assert!(
        evaluate_approx("2000000", "1000000", hundred_percent, 18).is_clean_pass(),
        "delta of exactly 100% with a 100% tolerance must pass (<= is inclusive)"
    );
    assert!(
        evaluate_approx("2000000", "1000000", hundred_percent - 1, 18).is_violation(),
        "one unit below the delta must fail"
    );
}

/// Basin's real property, expressed with the tolerance its own test uses.
#[test]
fn basin_total_supply_invariant_is_now_expressible() {
    // invariant_totalSupplyMatchesFunctionCalc compares totalSupply against
    // calcLpTokenSupply with a relative tolerance derived from the reserves' magnitude.
    // Here: supply 1_000_000 vs calc 1_000_000 within 1e-4 at precision 6.
    let outcome = evaluate_approx("1000000", "1000000", 100, 6);
    assert!(
        outcome.is_clean_pass(),
        "identical values pass, got {outcome:?}"
    );

    // A 1-unit drift at 1e6 is 1e-6 relative; tolerance 100 at precision 6 allows 1e-4
    // in the same units, so it passes.
    let outcome = evaluate_approx("1000001", "1000000", 100, 6);
    assert!(
        outcome.is_clean_pass(),
        "1e-6 drift within 1e-4, got {outcome:?}"
    );

    // A 1% drift (10_000 units at 1e6) is 1e-2 relative, far outside 1e-4.
    let outcome = evaluate_approx("1010000", "1000000", 100, 6);
    assert!(
        outcome.is_violation(),
        "1% drift must exceed a 1e-4 tolerance, got {outcome:?}"
    );
}

#[test]
fn approx_eq_rejects_malformed_arguments_at_compile_time() {
    // Wrong arity, missing commas, and a non-literal tolerance are all load-time errors
    // rather than surprises mid-campaign.
    for source in [
        "approx_eq(lpSupply, functionCalc)",
        "approx_eq(lpSupply, functionCalc, 10)",
        "approx_eq(lpSupply functionCalc, 10, 6)",
        "approx_eq(lpSupply, functionCalc, functionCalc, 6)",
        "approx_eq(lpSupply, functionCalc, 10, 6",
    ] {
        assert!(
            rustyfuzz_predicate::compile(source).is_err(),
            "`{source}` must not compile"
        );
    }
}

#[test]
fn approx_eq_composes_with_boolean_operators() {
    // A real invariant often conjoins an approximate check with an exact one, as Basin's
    // totalSupply invariant does (approximate equality *and* an inequality).
    let bindings = BindingManifest::from_json(MANIFEST)
        .expect("parses")
        .resolve()
        .expect("resolves");
    let checked = rustyfuzz_predicate::compile(
        "approx_eq(lpSupply, functionCalc, 100, 6) && lpSupply <= functionCalc",
    )
    .expect("compiles");

    let mut slot_a = [0u8; 32];
    slot_a[31] = 1;
    let mut slot_b = [0u8; 32];
    slot_b[31] = 2;
    let mut address = [0u8; 20];
    address[19] = 0xaa;
    let writes = vec![
        WriteRecord {
            tx_index: 0,
            address,
            slot: slot_a,
            old_value: [0u8; 32],
            new_value: big_endian("1000000"),
        },
        WriteRecord {
            tx_index: 0,
            address,
            slot: slot_b,
            old_value: [0u8; 32],
            new_value: big_endian("1000000"),
        },
    ];
    let resolver = Resolver::new(&bindings, &writes, &[], 0);
    let ctx = EvalContext {
        bindings: &bindings,
        resolver: &resolver,
        block: BlockContext::default(),
        tx_index: 0,
    };
    let mut reader = NoRead;
    let (outcome, _, _) =
        rustyfuzz_predicate::evaluate(checked.expr(), &ctx, &mut reader, ReReadBudget::new(4));
    assert!(
        outcome.is_clean_pass(),
        "both conjuncts hold, got {outcome:?}"
    );
}

#[test]
fn approx_eq_is_boolean_typed_and_rejects_bool_operands() {
    assert!(rustyfuzz_predicate::compile("approx_eq(a, b, 1, 6)").is_ok());
    // A boolean where an integer belongs is a type error.
    assert!(rustyfuzz_predicate::compile("approx_eq(a == b, b, 1, 6)").is_err());
    // And the result is a boolean, so using it in arithmetic fails.
    assert!(rustyfuzz_predicate::compile("approx_eq(a, b, 1, 6) + 1 > 2").is_err());
}

#[test]
fn approx_eq_evidence_names_both_operands() {
    // A finding from an approximate check must show the two values and the tolerance,
    // or a reader cannot tell whether the violation is real or a rounding artefact.
    let bindings = BindingManifest::from_json(MANIFEST)
        .expect("parses")
        .resolve()
        .expect("resolves");
    let checked =
        rustyfuzz_predicate::compile("approx_eq(lpSupply, functionCalc, 10, 6)").expect("compiles");
    assert_eq!(checked.symbols().len(), 2);
    let names: Vec<String> = checked
        .symbols()
        .iter()
        .map(|symbol| symbol.to_string())
        .collect();
    assert_eq!(names, vec!["lpSupply", "functionCalc"]);
    let _ = bindings;
    let _: BTreeMap<String, String> = BTreeMap::new();
}
